Highest Occurring Element in an Array.source:
import java.util.*;

public class Solution {
  public static Map<Integer, Integer> frequencies(int[] a) {
    Map<Integer, Integer> map = new TreeMap<>();
    for (int x : a) map.put(x, map.getOrDefault(x, 0) + 1);
    return map;
  }

  public static int solve(int[] a) {
    if (a.length == 0) throw new IllegalArgumentException("nonempty array required");
    int best = 0, count = -1;
    for (Map.Entry<Integer, Integer> e : frequencies(a).entrySet())
      if (e.getValue() > count) {
        best = e.getKey();
        count = e.getValue();
      }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {3, 2, 3, 2, 1}));
  }
}

Second Highest Occurring Element.source:
import java.util.*;

public class Solution {
  public static Map<Integer, Integer> frequencies(int[] a) {
    Map<Integer, Integer> map = new TreeMap<>();
    for (int x : a) map.put(x, map.getOrDefault(x, 0) + 1);
    return map;
  }

  public static OptionalInt solve(int[] a) {
    List<Map.Entry<Integer, Integer>> entries = new ArrayList<>(frequencies(a).entrySet());
    entries.sort(
        (x, y) -> {
          int c = Integer.compare(y.getValue(), x.getValue());
          return c != 0 ? c : Integer.compare(x.getKey(), y.getKey());
        });
    return entries.size() < 2 ? OptionalInt.empty() : OptionalInt.of(entries.get(1).getKey());
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 1, 2, 2, 2, 3}).getAsInt());
  }
}

Sum of Highest and Lowest Frequency.source:
import java.util.*;

public class Solution {
  public static Map<Integer, Integer> frequencies(int[] a) {
    Map<Integer, Integer> map = new TreeMap<>();
    for (int x : a) map.put(x, map.getOrDefault(x, 0) + 1);
    return map;
  }

  public static int solve(int[] a) {
    if (a.length == 0) return 0;
    int low = Integer.MAX_VALUE, high = 0;
    for (int f : frequencies(a).values()) {
      low = Math.min(low, f);
      high = Math.max(high, f);
    }
    return low + high;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 1, 2, 2, 2, 3}));
  }
}

